const D = { energy: .6, scale: 1, density: .5, speed: 1, wind: .5, hue: 28, x: .5, y: .34, style: 'paper', seed: 0, alpha: 100 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

// ---- Rows of festival paper lanterns strung on catenary wires across the upper frame,
// glowing warm and swinging on the wind. A SET: it hangs in a band and leaves the rest of
// the frame open so the bg reads through; alpha scales every mark (never an opaque panel).
// Not signage (set.neon_sign), not a fire (set.campfire). ----

const cl = (v,a,b) => v<a?a:(v>b?b:v);
const u = Math.min(width, height), sd = P.seed|0;
const fr = i => { const s = Math.sin(i*127.1 + sd*311.7)*43758.5453; return s - Math.floor(s); };
const sty = P.style, en = cl(P.energy,0,1), dn = cl(P.density,0,1), wnd = cl(P.wind,0,1);
const HU = ((P.hue%360)+360)%360, tt = K.t;
const ink = sty==='ink', bp = sty==='blueprint', riso = sty==='riso', fest = sty==='festoon';
const AL = cl(P.alpha,0,100);
if (AL > 0.5) {

const bass = (S.b = (S.b||0)*.84 + (A.bass||0)*.16);
const glowB = (.42+.58*en)*(.55+.5*K.intensity) + bass*.28;

// ---- soft glow sprite, built once (cheap per-lantern glow via tint()+image, no shadowBlur) ----
if (!S.spr){ const G=createGraphics(64,64); G.pixelDensity(1); G.loadPixels();
  for(let y=0;y<64;y++)for(let x=0;x<64;x++){ const dx=(x-32)/32,dy=(y-32)/32; const d=Math.sqrt(dx*dx+dy*dy);
    const a=Math.pow(cl(1-d,0,1),2.2)*255; const o=4*(y*64+x); G.pixels[o]=255;G.pixels[o+1]=255;G.pixels[o+2]=255;G.pixels[o+3]=a; }
  G.updatePixels(); S.spr=G; }

const cx = cl(P.x,.05,.95)*width, cy = cl(P.y,.08,.7)*height;
const rL = u*.030*cl(P.scale,.3,2.4);
const nStr = 2 + Math.round(dn*3);                       // 2..5 strings
const perStr = 6 + Math.round(dn*7);                     // lanterns per string
const spanW = width*1.15;

push();
translate(0,0);
for (let s=0;s<nStr;s++){
  const sy0 = cy + (s - (nStr-1)/2)*rL*3.4;               // stack the strings in a band
  const ph = fr(s*7.3)*6.28;
  // whole-string wind sway + a slow sag breathing (incommensurate real-time rates)
  const sag = (u*.05 + u*.05*wnd) * (1 + .5*Math.sin(tt*.19*P.speed + ph));
  const drift = (u*.02+u*.05*wnd)*(.7*Math.sin(tt*.23*P.speed+ph)+.4*Math.sin(tt*.41*P.speed+ph*1.7));
  const x0 = cx - spanW*.5 + drift*.3, x1 = cx + spanW*.5 + drift*.3;
  const wy0 = sy0 + (fr(s*3.1)-.5)*rL*1.5, wy1 = sy0 + (fr(s*5.7)-.5)*rL*1.5;
  // ---- the wire (thin, taut catenary) ----
  if (!ink){
    stroke(bp?200:HU, bp?30:10, bp?100:38, (ink?0:26)*AL/100);
    strokeWeight(Math.max(1,u*.0012)); noFill();
    beginShape();
    for (let k=0;k<=24;k++){ const q=k/24; const wx=x0+(x1-x0)*q;
      const wy=wy0+(wy1-wy0)*q + sag*4*q*(1-q); vertex(wx,wy); }
    endShape();
  }
  // ---- the lanterns hung along it ----
  for (let n=0;n<perStr;n++){
    const q=(n+.5)/perStr; const wx=x0+(x1-x0)*q;
    const wy=wy0+(wy1-wy0)*q + sag*4*q*(1-q);
    // pendulum swing with phase lag along the string -> a wave travels the row
    const lag = q*4.0 + ph;
    const swing = (0.10+0.34*wnd)*(Math.sin(tt*(1.0+ .12*s)*P.speed + lag) + .4*Math.sin(tt*1.7*P.speed+lag*1.4));
    const hl = rL*2.2;
    const lx = wx + hl*Math.sin(swing);
    const ly = wy + hl*Math.cos(swing) + rL*.4;
    const li = fr(s*31.7+n*13.3);
    // slow warm flicker per lantern (never a strobe)
    const flick = .72 + .28*Math.sin(tt*(.7+li*.9) + li*6.28);
    const on = glowB*flick;
    const w = rL*(fest?.5:1.5), h = rL*(fest?.7:1.9);
    // hue drift a little per lantern
    const lh = (HU + (li-.5)*30 + 360)%360;
    // glow halo (ADD)
    if (!ink && !bp){
      push(); blendMode(ADD); noStroke();
      const gsz = rL*(fest?4.2:5.0)*(.7+on*.6);
      tint(fest?45:lh, fest?24:44, 100, cl((fest?24:16)*on*AL/100,0,60));
      image(S.spr, lx-gsz/2, ly-gsz/2, gsz, gsz);
      noTint(); blendMode(BLEND); pop();
    }
    // hanging string from wire to cap
    if (!ink){ stroke(bp?200:lh, bp?30:12, bp?100:30, 30*AL/100); strokeWeight(Math.max(1,u*.001));
      line(wx,wy,lx,ly-h*.5); }
    // body
    if (bp){
      noFill(); stroke(196,60,100,80*AL/100); strokeWeight(Math.max(1,u*.0016));
      ellipse(lx,ly,w*2,h*2);
      line(lx,ly-h,lx,ly+h);
    } else if (ink){
      noStroke(); fill(HU,14,10, 92*AL/100); ellipse(lx,ly,w*2,h*2);
      fill(HU,14,4, 96*AL/100); ellipse(lx,ly-h*.9,w*.7,h*.35);   // cap silhouette
    } else if (fest){
      noStroke(); fill(45,20,100, cl(70+on*30,0,100)*AL/100); ellipse(lx,ly,w*2,h*2);
      fill(48,10,100, cl(90*on,0,100)*AL/100); ellipse(lx-w*.3,ly-h*.3,w,h);  // filament hot spot
    } else {
      // paper lantern: warm translucent body, lit from within, ribbed
      noStroke();
      const base = cl(28+on*30,0,100);
      fill(lh, riso?70:52, cl(base,10,96), (riso?86:82)*AL/100);
      ellipse(lx,ly,w*2,h*2);
      // inner glow core
      push(); blendMode(riso?BLEND:ADD);
      fill(lh, riso?50:34, 100, cl(30*on,0,70)*AL/100); ellipse(lx,ly,w*1.3,h*1.3);
      blendMode(BLEND); pop();
      // vertical ribs (texture, not flat fill)
      stroke(lh, 60, base*.5, 34*AL/100); strokeWeight(Math.max(1,u*.0009)); noFill();
      for(let rb=-2;rb<=2;rb++){ const rx=rb/2.4; const bx=lx+rx*w;
        beginShape(); for(let vv=-3;vv<=3;vv++){ const ty=vv/3; const bw=Math.sqrt(cl(1-ty*ty,0,1));
          vertex(lx+rx*w*bw, ly+ty*h*.96); } endShape(); }
      // top cap + bottom tassel
      noStroke(); fill(HU, ink?14:44, base*.42, 80*AL/100);
      ellipse(lx,ly-h*.92,w*.8,h*.28); ellipse(lx,ly+h*.92,w*.5,h*.22);
      stroke(HU,50,base*.4,60*AL/100); strokeWeight(Math.max(1,u*.001));
      line(lx,ly+h,lx,ly+h+rL*.7);
    }
  }
}
pop();
blendMode(BLEND); noTint(); drawingContext.shadowBlur=0; strokeWeight(1);
}
